/*
 * String classification functions: check if all characters in a string
 * satisfy a predicate. Returns true if all characters satisfy the predicate
 * and there is at least one character, false otherwise.
 */

template <typename character>
static inline int
check_char_isalpha(character c)
{
    return ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'));
}

template <typename character>
static inline int
check_char_isdigit(character c)
{
    return (c >= '0' && c <= '9');
}

template <typename character>
static inline int
check_char_isspace(character c)
{
    return (c == ' ' || c == '\f' || c == '\n' || c == '\r' || c == '\t' || c == '\v');
}

template <typename character>
static inline int
check_char_isalnum(character c)
{
    return check_char_isalpha(c) || check_char_isdigit(c);
}

template <typename character, int (*check_fn)(character)>
static int
string_check_all_loop(PyArrayMethod_Context *context,
        char *const data[], npy_intp const dimensions[],
        npy_intp const strides[], NpyAuxData *NPY_UNUSED(auxdata))
{
    int len = context->descriptors[0]->elsize / sizeof(character);

    char *in = data[0];
    char *out = data[1];
    npy_intp N = dimensions[0];

    while (N--) {
        int has_char = 0;
        int all_match = 1;
        for (int i = 0; i < len; i++) {
            character c = ((character *)in)[i];
            /* Skip null padding characters */
            if (sizeof(character) == 1 && c == '\0') {
                break;
            }
            else if (sizeof(character) == 4 && c == 0) {
                break;
            }
            has_char = 1;
            if (!check_fn(c)) {
                all_match = 0;
                break;
            }
        }
        *(npy_bool *)out = (all_match && has_char) ? 1 : 0;

        in += strides[0];
        out += strides[1];
    }
    return 0;
}

/*
 * Machinery to add string classification loops.
 */
template <typename character, int (*check_fn)(character)>
static int
add_string_check_loop(PyObject *umath, const char *ufunc_name, PyArrayMethod_Spec *spec)
{
    PyObject *name = PyUnicode_FromString(ufunc_name);
    if (name == nullptr) {
        return -1;
    }
    PyObject *ufunc = PyObject_GetItem(umath, name);
    Py_DECREF(name);
    if (ufunc == nullptr) {
        return -1;
    }

    PyArrayMethod_StridedLoop *loop = string_check_all_loop<character, check_fn>;
    spec->slots[0].pfunc = (void *)loop;

    int res = PyUFunc_AddLoopFromSpec(ufunc, spec);
    Py_DECREF(ufunc);
    return res;
}
