            has_char = 1;
            if (!check_fn(c)) {
                all_match = 0;
                break;
            }
        }
        *(npy_bool *)out = (all_match && has_char) ? 1 : 0;
        in += strides[0];
        out += strides[1];
    }
    return 0;
}

