/*
 * Vectorized string check function - processes strings directly in C
 * without going through Python string methods.
 * Returns true if all characters in the string are alphabetic.
 */
static int
vectorized_isalpha_str(npy_char *string, npy_intp len)
{
    npy_intp i;
    int has_char = 0;
    for (i = 0; i < len; i++) {
        npy_char c = string[i];
        /* Stop at null terminator */
        if (c == '\0') {
            break;
        }
        has_char = 1;
        if (!NumPyOS_ascii_isalpha(c)) {
            return 0;
        }
    }
    return has_char;
}

