/* Inline character check - avoids dependency on NumPyOS_ascii_isalpha */
static inline int
local_isalpha(npy_char c)
{
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

/* Vectorized string check function */
static int
vectorized_isalpha_str(npy_char *string, npy_intp len)
{
    npy_intp i;
    int has_char = 0;
    for (i = 0; i < len; i++) {
        npy_char c = string[i];
        if (c == 0) {
            break;
        }
        has_char = 1;
        if (!local_isalpha(c)) {
            return 0;
        }
    }
    return has_char;
}
